begin;

create extension if not exists pgtap with schema extensions;
select plan(46);

select has_table('public', 'operator_incidents', 'operator incidents exist');
select has_table('public', 'operator_incident_timeline', 'operator incident timeline exists');
select has_function('public', 'list_operator_incidents', array['integer'], 'incident read RPC exists');
select has_function('public', 'transition_operator_incident', array['uuid', 'text', 'text', 'bigint', 'text'], 'incident transition RPC exists');
select has_function('public', 'create_operator_incident', array['text', 'text', 'text', 'timestamptz', 'text', 'text', 'text', 'text', 'text'], 'incident create RPC exists');
select has_function('public', 'record_operator_incident_recovery', array['uuid', 'text', 'text', 'text', 'bigint', 'text'], 'incident recovery evidence RPC exists');
select ok(has_function_privilege('authenticated', 'public.list_operator_incidents(integer)', 'EXECUTE'), 'authenticated operators can read incidents');
select ok(not has_function_privilege('anon', 'public.list_operator_incidents(integer)', 'EXECUTE'), 'anonymous users cannot read incidents');
select ok(not has_table_privilege('authenticated', 'public.operator_incidents', 'SELECT'), 'authenticated users cannot read incident tables directly');
select ok((select relrowsecurity from pg_class where oid = 'public.operator_incidents'::regclass), 'incident table retains RLS');
select ok((select relrowsecurity from pg_class where oid = 'public.operator_incident_timeline'::regclass), 'timeline table retains RLS');
select ok(pg_get_functiondef(to_regprocedure('public.list_operator_incidents(integer)')) like '%system.read%', 'incident read requires system.read');
select ok(pg_get_functiondef(to_regprocedure('public.list_operator_incidents(integer)')) like '%aal2%', 'incident read requires MFA assurance');
select ok((select pg_get_constraintdef(oid) like '%conversation_jobs%' from pg_constraint where conname = 'operator_incidents_source_check' and conrelid = 'public.operator_incidents'::regclass), 'incidents retain observation source');
select ok(pg_get_functiondef(to_regprocedure('public.list_operator_incidents(integer)')) like '%source_observed_at%', 'incidents retain source observation timestamp');
select ok(pg_get_functiondef(to_regprocedure('public.list_operator_incidents(integer)')) like '%fact_kind%', 'incidents retain fact kind');
select ok(pg_get_functiondef(to_regprocedure('public.list_operator_incidents(integer)')) like '%rollback_candidate_code%', 'incidents retain rollback candidate fact');
select ok(pg_get_functiondef(to_regprocedure('public.list_operator_incidents(integer)')) like '%recovery_state%', 'incidents retain recovery verification state');
select ok(pg_get_functiondef(to_regprocedure('public.list_operator_incidents(integer)')) not like '%raw_log%' and pg_get_functiondef(to_regprocedure('public.list_operator_incidents(integer)')) not like '%secret%', 'incident read excludes raw logs and secrets');
select ok(pg_get_functiondef(to_regprocedure('public.list_operator_incidents(integer)')) like '%order by%', 'incident read has deterministic ordering');
select ok(pg_get_functiondef(to_regprocedure('public.transition_operator_incident(uuid,text,text,bigint,text)')) like '%incident.manage%', 'incident mutation requires incident.manage');
select ok(pg_get_functiondef(to_regprocedure('public.transition_operator_incident(uuid,text,text,bigint,text)')) like '%aal2%', 'incident mutation requires MFA assurance');
select ok(pg_get_functiondef(to_regprocedure('public.transition_operator_incident(uuid,text,text,bigint,text)')) like '%expected_version%', 'incident mutation checks expected version');
select ok(pg_get_functiondef(to_regprocedure('public.transition_operator_incident(uuid,text,text,bigint,text)')) like '%idempotency_key%', 'incident mutation checks idempotency');
select ok(pg_get_functiondef(to_regprocedure('public.transition_operator_incident(uuid,text,text,bigint,text)')) like '%resulting_status%', 'timeline stores resulting status');
select ok(pg_get_functiondef(to_regprocedure('public.transition_operator_incident(uuid,text,text,bigint,text)')) like '%resulting_recovery_state%', 'timeline stores resulting recovery state');
select ok(pg_get_functiondef(to_regprocedure('public.transition_operator_incident(uuid,text,text,bigint,text)')) like '%replayed%', 'transition returns deterministic replay result');
select ok(pg_get_functiondef(to_regprocedure('public.transition_operator_incident(uuid,text,text,bigint,text)')) like '%acknowledge%', 'acknowledge transition exists');
select ok(pg_get_functiondef(to_regprocedure('public.transition_operator_incident(uuid,text,text,bigint,text)')) like '%resolve%', 'resolve transition exists');
select ok(pg_get_functiondef(to_regprocedure('public.transition_operator_incident(uuid,text,text,bigint,text)')) like '%reopen%', 'reopen transition exists');
select ok(pg_get_functiondef(to_regprocedure('public.transition_operator_incident(uuid,text,text,bigint,text)')) like '%incident.recovery_state <> ''verified''%', 'resolve requires verified recovery');
select ok(pg_get_functiondef(to_regprocedure('public.transition_operator_incident(uuid,text,text,bigint,text)')) like '%pending%', 'reopen explicitly returns to pending recovery');
select ok(pg_get_functiondef(to_regprocedure('public.transition_operator_incident(uuid,text,text,bigint,text)')) like '%status = ''open''%', 'transition validates current status');
select ok(pg_get_functiondef(to_regprocedure('public.transition_operator_incident(uuid,text,text,bigint,text)')) like '%version = version + 1%', 'transition increments incident version');
select ok(pg_get_functiondef(to_regprocedure('public.transition_operator_incident(uuid,text,text,bigint,text)')) like '%operator_incident_timeline%', 'transition appends immutable timeline');
select ok(pg_get_functiondef(to_regprocedure('public.create_operator_incident(text,text,text,timestamptz,text,text,text,text,text)')) like '%operator_incident_timeline%', 'create appends opened timeline in the same transaction');
select ok(pg_get_functiondef(to_regprocedure('public.create_operator_incident(text,text,text,timestamptz,text,text,text,text,text)')) like '%incident.manage%', 'create requires incident.manage');
select ok(pg_get_functiondef(to_regprocedure('public.record_operator_incident_recovery(uuid,text,text,text,bigint,text)')) like '%rollback_candidate_code%', 'recovery records rollback candidate');
select ok(pg_get_functiondef(to_regprocedure('public.record_operator_incident_recovery(uuid,text,text,text,bigint,text)')) like '%recovery_verification_recorded%', 'recovery appends verification timeline');
select ok(pg_get_functiondef(to_regprocedure('public.record_operator_incident_recovery(uuid,text,text,text,bigint,text)')) like '%expected_version%', 'recovery checks expected version');
select ok(pg_get_functiondef(to_regprocedure('public.transition_operator_incident(uuid,text,text,bigint,text)')) not like '%delete from public.operator_incident%', 'transition cannot delete timeline');
select ok((select pg_get_constraintdef(oid) like '%observed%' from pg_constraint where conname = 'operator_incidents_fact_kind_check' and conrelid = 'public.operator_incidents'::regclass), 'read model preserves observed facts');
select ok((select pg_get_constraintdef(oid) like '%user_claim%' from pg_constraint where conname = 'operator_incidents_fact_kind_check' and conrelid = 'public.operator_incidents'::regclass), 'read model preserves user claim facts');
select ok((select pg_get_constraintdef(oid) like '%inference%' from pg_constraint where conname = 'operator_incidents_fact_kind_check' and conrelid = 'public.operator_incidents'::regclass), 'read model preserves inference facts');
select ok((select pg_get_constraintdef(oid) like '%unknown%' from pg_constraint where conname = 'operator_incidents_fact_kind_check' and conrelid = 'public.operator_incidents'::regclass), 'read model preserves unknown facts');
select ok(not has_function_privilege('anon', 'public.transition_operator_incident(uuid,text,text,bigint,text)', 'EXECUTE'), 'anonymous users cannot transition incidents');

rollback;
